16	// --- Access control -----------------------------------------------------------
17	// Gate Scanner / V-Patrol run under an FM session. A trusted edge device (e.g. a
18	// future Pi node posting frames itself) may authenticate with EDGE_SERVICE_TOKEN
19	// in an x-edge-token header instead of a user JWT.
20	const allowFMOrEdgeService = (req, res, next) => {
21	  const edgeToken = req.headers['x-edge-token'];
22	  if (edgeToken && process.env.EDGE_SERVICE_TOKEN && edgeToken === process.env.EDGE_SERVICE_TOKEN) {
23	    return next();
