29	const validateFrame = (image) => {
30	  if (typeof image !== 'string' || !image.startsWith('data:image/')) {
31	    return { status: 400, error: 'A base64 data-URL image is required.' };
32	  }
33	  if (image.length > MAX_IMAGE_CHARS) {
34	    return { status: 413, error: 'Image payload too large.' };
35	  }
36	  return null;
37	};
38	
39	const forwardRecognitionFrame = async (image) => {
40	  const startedAt = Date.now();
41	  const aiResponse = await axios.post(`${FACE_AI_URL()}/user/recognize`, { image }, {
42	    timeout: 15000,
43	    headers: { 'X-AI-Service-Key': process.env.AI_SERVICE_KEY || '' }
44	  });
