48	const livenessStatus = (ratio) => {
49	  if (typeof ratio !== 'number') return 'unavailable';
50	  return ratio < 0.35 || ratio > 0.65 ? 'movement-detected' : 'front-facing';
51	};
52	
53	// GET is intentionally read-only; POST performs the explicit FM-controlled backfill.
54	router.get('/evaluation-participants', verifyToken, requireRole('FM'), async (_req, res) => {
55	  try { return res.status(200).json({ participants: await listEvaluationParticipants() }); }
