59	  try { const assigned = await syncEligibleEvaluationParticipants(); return res.status(200).json({ synced: assigned.length, participants: await listEvaluationParticipants() }); }
60	  catch (error) { console.error('Evaluation participant sync error:', error); return res.status(500).json({ error: 'Could not sync evaluation participants.' }); }
61	});
62	// POST /api/facial-recognition/evaluate
63	// FM-only side-effect-free model evaluation. It forwards one temporary frame to
64	// FastAPI and returns safe telemetry only. It never creates Attendance,
65	// SecurityLogs, User updates, or enrolment changes, and never stores the frame.
66	router.post('/evaluate', verifyToken, requireRole('FM'), async (req, res) => {
67	  const validation = validateFrame(req.body?.image);
68	  if (validation) return res.status(validation.status).json({ error: validation.error });
69	
70	  try {
71	    const { aiResult, totalRequestMs } = await forwardRecognitionFrame(req.body.image);
72	    const {
73	      matchedUserId = null,
74	      confidence = 0,
75	      box = null,
76	      liveness_ratio = null,
77	      faceDetected = false,
78	      inference_ms = null
79	    } = aiResult;
80	
81	    const outcome = faceDetected === false || (!box && matchedUserId == null)
82	      ? 'NO_FACE'
83	      : matchedUserId == null ? 'UNKNOWN' : 'MATCHED';
84	
85	    let subject = null;
86	    if (matchedUserId != null) {
87	      const user = await User.findByPk(matchedUserId, {
88	        attributes: ['id', 'name', 'role', 'isActive', 'isEnrolled']
89	      });
90	      if (user) {
