92	        subject = {
93	          id: user.id,
94	          name: user.name,
95	          role: user.role,
96	          isActive: Boolean(user.isActive),
97	          isEnrolled: Boolean(user.isEnrolled),
98	          evaluationLabel: participant?.evaluationLabel || null
99	        };
100	      }
101	    }
102	    const policyDecision = outcome === 'NO_FACE' ? 'NONE'
103	      : subject?.isActive && subject?.isEnrolled ? 'GRANTED' : 'DENIED';
104	
105	    // Still-image policy evaluation excludes live anti-spoofing/head-turn verification.
106	    return res.status(200).json({
107	      matchedUserId: matchedUserId == null ? null : matchedUserId,
108	      outcome,
109	      confidence,
110	      box,
111	      subject,
