137	  }
138	});
139	// POST /api/facial-recognition/access-event
140	// V-Patrol monitoring: records a server-owned SAFE access audit event for a
141	// verified (recognised + liveness-passed) active user WITHOUT touching
142	// attendance - V-Patrol must never toggle clock-in/out; that is the Gate
143	// Scanner's job via /api/attendance/scan. Deduplicated server-side.
144	router.post('/access-event', allowFMOrEdgeService, async (req, res) => {
145	  try {
146	    const { userId, cameraLocation } = req.body;
147	    if (userId == null || !Number.isInteger(Number(userId))) {
148	      return res.status(400).json({ error: 'Missing required parameter: userId' });
149	    }
150	    const location = typeof cameraLocation === 'string' && cameraLocation.trim()
151	      ? cameraLocation.trim().slice(0, 100)
152	      : 'Biometric Gantry';
153	
154	    const user = await User.findByPk(userId, {
155	      attributes: ['id', 'name', 'role', 'isActive', 'isEnrolled']
156	    });
157	    if (!user || !user.isEnrolled) {
158	      return res.status(404).json({ error: 'User not recognized in system registry.' });
159	    }
160	    if (!user.isActive) {
161	      return res.status(403).json({ error: 'Account suspended. Access event not recorded as granted.' });
162	    }
163	
164	    // Same dedup namespace as the attendance scan, so a person passing both the
165	    // gantry and the turnstile within the cooldown yields ONE safe log, not two.
166	    let logged = false;
167	    if (shouldWriteLog(`granted:${user.id}:${location}`)) {
168	      logged = await createSecurityLog({
169	        type: 'Gantry Access',
170	        desc: `Identity & liveness verified: ${user.name} (${user.role}) at ${location}.`,
171	        severity: 'safe',
172	        // Stable token — the client renders the matching MUI icon.
173	        icon: 'UNLOCK',
174	        personnelName: user.name,
175	        matchedUserId: user.id,
176	        cameraLocation: location
177	      });
178	    }
179	
180	    // Safe fields only - never the biometric template.
181	    return res.status(200).json({
182	      status: 'SUCCESS',
183	      logged,
184	      worker: user.name,
185	      role: user.role
186	    });
187	  } catch (err) {
188	    console.error('Access-event error:', err);
189	    return res.status(500).json({ error: 'Could not record access event.' });
190	  }
191	});
192	
193	// POST /api/facial-recognition/track
194	// Lightweight, side-effect-free face tracking for the scanners' live overlay
195	// and head-turn movement sampling. Forwards one temporary frame to FastAPI's
196	// detection-only endpoint and returns SAFE transient telemetry (box, count,
197	// head-turn ratio) — never an identity, never a database read/write, never a
198	// SecurityLog or Attendance record. Tracking alone can never grant access.
199	const TRACK_TIMEOUT_MS = 5000; // much shorter than full recognition (15s)
200	
201	router.post('/track', allowFMOrEdgeService, async (req, res) => {
202	  const validation = validateFrame(req.body?.image);
203	  if (validation) return res.status(validation.status).json({ error: validation.error });
204	
205	  try {
206	    const aiResponse = await axios.post(`${FACE_AI_URL()}/user/track`, { image: req.body.image }, {
207	      timeout: TRACK_TIMEOUT_MS,
208	      headers: { 'X-AI-Service-Key': process.env.AI_SERVICE_KEY || '' }
209	    });
210	    const {
211	      faceDetected = false,
212	      faceCount = 0,
213	      box = null,
214	      headTurnRatio = null,
215	      inferenceMs = null
216	    } = aiResponse.data || {};
217	
218	    // Whitelisted safe fields only — nothing else from the AI reply passes through.
219	    return res.status(200).json({ faceDetected, faceCount, box, headTurnRatio, inferenceMs });
220	  } catch (err) {
221	    const isConnError = !err.response &&
222	      ['ECONNREFUSED', 'ECONNABORTED', 'ETIMEDOUT', 'ENOTFOUND'].includes(err.code);
223	    if (isConnError) {
224	      return res.status(503).json({ error: 'Face tracking service is offline. Please try again shortly.' });
225	    }
226	    if (err.response) {
227	      const status = err.response.status === 400 ? 400 : 502;
228	      return res.status(status).json({ error: 'Face tracking service returned an error.' });
229	    }
230	    console.error('Tracking forwarding error:', err.message);
231	    return res.status(502).json({ error: 'Face tracking service returned an error.' });
232	  }
233	});
234	
235	// POST /api/facial-recognition/recognize
236	// Frontend (Gate Scanner / V-Patrol) -> Node -> FastAPI -> Node resolves the User
237	// record from PostgreSQL -> safe recognition result. The DB - not the AI cache -
238	// decides name, role, account status, and the access outcome.
239	router.post('/recognize', allowFMOrEdgeService, async (req, res) => {
240	  const { image, cameraLocation } = req.body;
241	
242	  const validation = validateFrame(image);
243	  if (validation) return res.status(validation.status).json({ error: validation.error });
244	  const location = typeof cameraLocation === 'string' && cameraLocation.trim()
245	    ? cameraLocation.trim().slice(0, 100)
246	    : 'Main Gate';
247	
248	  let aiResult;
249	  const aiStartedAt = Date.now();
250	  try {
251	    const aiResponse = await axios.post(`${FACE_AI_URL()}/user/recognize`, { image }, {
252	      timeout: 15000,
253	      headers: { 'X-AI-Service-Key': process.env.AI_SERVICE_KEY || '' }
254	    });
255	    aiResult = aiResponse.data;
256	  } catch (err) {
257	    const isConnError = !err.response &&
258	      ['ECONNREFUSED', 'ECONNABORTED', 'ETIMEDOUT', 'ENOTFOUND'].includes(err.code);
259	    if (isConnError) {
260	      return res.status(503).json({ error: 'Facial recognition service is offline. Please try again shortly.' });
261	    }
262	    if (err.response) {
263	      const status = err.response.status === 400 ? 400 : 502;
264	      return res.status(status).json({ error: 'Facial recognition service returned an error.' });
265	    }
266	    console.error('Recognition forwarding error:', err.message);
267	    return res.status(502).json({ error: 'Facial recognition service returned an error.' });
268	  }
269	
270	  const { matchedUserId, confidence = 0, box = null, liveness_ratio = 0.5, faceDetected, inference_ms = null } = aiResult || {};
271	
272	  // Development timing telemetry - durations only, never images or templates.
273	  const nodeToAiMs = Date.now() - aiStartedAt;
274	  const timings = { nodeToAiMs, inferenceMs: inference_ms, totalRequestMs: nodeToAiMs };
275	  if (process.env.NODE_ENV !== 'production') {
276	    console.log(`[recognize] Node->FastAPI ${timings.nodeToAiMs}ms, InsightFace inference ${inference_ms ?? '?'}ms`);
277	  }
278	
279	  // No face in frame -> no recognition attempt, and no suspicious-person log.
280	  if (faceDetected === false || (!box && matchedUserId == null)) {
281	    return res.status(200).json({ user: null, box: null, liveness_ratio, timings });
282	  }
283	
284	  // Face detected but no template match -> unknown person.
285	  if (matchedUserId == null) {
286	    if (shouldWriteLog(`unknown:${location}`)) {
287	      await createSecurityLog({
288	        type: 'Intrusion Alert',
289	        desc: `Unregistered person detected at ${location} (confidence ${Number(confidence).toFixed(2)}).`,
290	        severity: 'critical',
291	        icon: 'ALERT',
292	        personnelName: null,
293	        confidence,
294	        cameraLocation: location
295	      });
296	    }
297	    return res.status(200).json({
298	      user: { id: null, name: 'Unknown Person', role: null, status: 'DENIED', confidence },
299	      box,
300	      liveness_ratio,
301	      timings
302	    });
303	  }
304	
305	  // Authoritative record: PostgreSQL, looked up by the unique matched user ID.
306	  const user = await User.findByPk(matchedUserId, {
307	    attributes: ['id', 'name', 'role', 'isActive', 'isEnrolled']
308	  });
309	
310	  // Matched an ID the DB no longer knows (e.g. off-boarded but AI cache stale).
311	  if (!user || !user.isEnrolled) {
312	    if (shouldWriteLog(`stale:${matchedUserId}:${location}`)) {
313	      await createSecurityLog({
314	        type: 'Intrusion Alert',
315	        desc: `Recognition matched a non-enrolled or removed account (ref #${matchedUserId}) at ${location}. AI cache may need a refresh.`,
316	        severity: 'critical',
317	        icon: 'ALERT',
318	        personnelName: null,
319	        matchedUserId,
320	        confidence,
321	        cameraLocation: location
322	      });
323	    }
324	    return res.status(200).json({
325	      user: { id: null, name: 'Unknown Person', role: null, status: 'DENIED', confidence },
326	      box,
327	      liveness_ratio,
328	      timings
329	    });
330	  }
331	
332	  // Suspended account -> deny access and audit it.
333	  if (!user.isActive) {
334	    if (shouldWriteLog(`suspended:${user.id}:${location}`)) {
335	      await createSecurityLog({
336	        type: 'Suspended Access Attempt',
337	        desc: `Suspended account attempted gate access at ${location}: ${user.name} (${user.role}, confidence ${Number(confidence).toFixed(2)}).`,
338	        severity: 'critical',
339	        icon: 'DENIED',
340	        personnelName: user.name,
341	        matchedUserId: user.id,
342	        role: user.role,
343	        confidence,
344	        cameraLocation: location
345	      });
346	    }
347	    return res.status(200).json({
348	      user: { id: user.id, name: user.name, role: user.role, status: 'SUSPENDED', confidence },
349	      box,
350	      liveness_ratio,
351	      timings
352	    });
353	  }
354	
355	  // Active, enrolled, recognised -> safe fields only.
356	  return res.status(200).json({
357	    user: { id: user.id, name: user.name, role: user.role, status: 'AUTHORIZED', confidence },
358	    box,
359	    liveness_ratio,
360	    timings
361	  });
362	});
363	
364	module.exports = router;
