857	                {EVENT_FILTERS.map(f => <option key={f.value} value={f.value}>{f.label}</option>)}
858	              </select>
859	              <input
860	                type="text"
861	                className="timeline-filter timeline-search"
862	                placeholder="Search name / role / location..."
863	                value={searchFilter}
864	                onChange={(e) => setSearchFilter(e.target.value)}
865	                aria-label="Search timeline"
866	              />
867	              {hasActiveFilters(activeFilters) && (
868	                <button
869	                  type="button"
870	                  className="timeline-clear-btn"
871	                  onClick={() => { setDateFilter('all'); setEventFilter('all'); setSearchFilter(''); }}
872	                >
873	                  Clear Filters
874	                </button>
875	              )}
876	            </div>
877	
878	            <div className="vpatrol-list">
879	              {incidentLogs.length === 0 ? (
880	                <p>Initializing security sensors...</p>
881	              ) : filteredLogs.length === 0 ? (
882	                <div className="timeline-empty">
883	                  <p>No security events match the current filters.</p>
884	                  <button
885	                    type="button"
886	                    className="timeline-clear-btn"
887	                    onClick={() => { setDateFilter('all'); setEventFilter('all'); setSearchFilter(''); }}
888	                  >
889	                    Clear Filters
890	                  </button>
891	                </div>
892	              ) : filteredLogs.map((log) => {
893	                const accessResult = deriveAccessResult(log);
894	                const timestamp = getLogTimestamp(log);
895	                const timeLabel = formatSingaporeTimestamp(timestamp) || log.time || 'Unknown time';
896	                const confidencePct = typeof log.confidence === 'number'
897	                  ? `${Math.round(log.confidence * 100)}%` : null;
898	                return (
899	                  <div key={log.id} className={`vpatrol-item ${log.severity}`}>
900	                    {/* Primary: event, person, outcome */}
901	                    <div className="item-body">
902	                      <div className="item-icon"><SecurityLogIcon log={log} /></div>
903	                      <div className="item-text">
904	                        <div className="item-title-row">
905	                          <h4>{log.type}</h4>
906	                          <span className={`access-result-badge result-${accessResult.toLowerCase()}`}>
907	                            {accessResult}
908	                          </span>
909	                        </div>
910	                        <p className="item-person">
911	                          {log.personnelName || 'Unknown Person'}
912	                          {log.role ? <span className="item-role"> | {log.role}</span> : null}
913	                        </p>
914	                        <p className="item-meta" title={formatSingaporeFull(timestamp) || undefined}>
915	                          {timeLabel}
916	                          {confidencePct ? ` | ${confidencePct} confidence` : ''}
917	                          {log.cameraLocation ? ` | ${log.cameraLocation}` : ''}
918	                        </p>
919	                        <p className="item-desc">{log.desc}</p>
920	                      </div>
921	                    </div>
922	                    {/* Secondary: muted UUID + review status */}
923	                    <div className="item-footer-muted">
924	                      <span className="item-id-muted">#{log.id}</span>
925	                      {log.reviewStatus ? <span className="item-review-status">{log.reviewStatus}</span> : null}
926	                    </div>
927	                  </div>
928	                );
929	              })}
