2	// The Node route forwards frames to FastAPI, then resolves identity, role and
3	// account status from PostgreSQL (the source of truth), never from AI metadata.
4	const request = require("supertest");
5	const express = require("express");
6	const jwt = require("jsonwebtoken");
7	
8	const mockUser = { findByPk: jest.fn() };
9	const mockSecurityLog = { create: jest.fn() };
10	const mockEvaluationParticipant = { findOne: jest.fn() };
11	const mockParticipantService = { listEvaluationParticipants: jest.fn(), syncEligibleEvaluationParticipants: jest.fn() };
