13	jest.mock("../../services/evaluationParticipants", () => mockParticipantService);
14	
15	const mockAxios = { post: jest.fn() };
16	jest.mock("axios", () => mockAxios);
17	
18	process.env.APP_SECRET = "test-secret";
19	process.env.FACE_AI_URL = "http://fake-ai:8501";
20	process.env.AI_SERVICE_KEY = "test-ai-key";
21	process.env.EDGE_SERVICE_TOKEN = "test-edge-token";
22	
23	const facialRecognitionRouter = require("../../routes/facialRecognition");
24	
