52	describe("POST /api/facial-recognition/recognize - access control", () => {
53	  beforeEach(() => {
54	    jest.clearAllMocks();
55	    primeDb();
56	  });
57	
58	  test("unauthenticated request -> 401", async () => {
59	    const res = await request(app)
