66	  test("Staff token -> 403 (FM only)", async () => {
67	    const res = await request(app)
68	      .post("/api/facial-recognition/recognize")
69	      .set("Authorization", `Bearer ${staffToken}`)
70	      .send({ image: FRAME });
71	    expect(res.status).toBe(403);
72	  });
73	
74	  test("trusted edge token authenticates without a JWT", async () => {
75	    aiReplies({ matchedUserId: null, confidence: 0, box: null, liveness_ratio: 0.5, faceDetected: false });
76	    const res = await request(app)
77	      .post("/api/facial-recognition/recognize")
78	      .set("x-edge-token", "test-edge-token")
79	      .send({ image: FRAME, cameraLocation: nextLocation() });
80	    expect(res.status).toBe(200);
