82	
83	  test("wrong edge token without JWT -> 401", async () => {
84	    const res = await request(app)
85	      .post("/api/facial-recognition/recognize")
86	      .set("x-edge-token", "wrong-token")
87	      .send({ image: FRAME });
88	    expect(res.status).toBe(401);
89	  });
90	});
91	
92	describe("POST /api/facial-recognition/recognize - validation & AI forwarding", () => {
93	  beforeEach(() => {
94	    jest.clearAllMocks();
95	    primeDb();
96	  });
97	
98	  test("missing / non-data-URL image -> 400", async () => {
99	    const res = await request(app)
100	      .post("/api/facial-recognition/recognize")
101	      .set("Authorization", `Bearer ${fmToken}`)
102	      .send({ image: "not-an-image" });
103	    expect(res.status).toBe(400);
104	    expect(mockAxios.post).not.toHaveBeenCalled();
105	  });
106	
107	  test("forwards the frame to FastAPI with the X-AI-Service-Key header", async () => {
